import { useState } from "react";
import "./index.css";

function App() {
  const [count, setCount] = useState(0);

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center px-4">

      {/* TITLE */}
      <h1 className="text-4xl font-bold text-blue-600 mb-4">
        Vite + React + Tailwind
      </h1>

      {/* CARD */}
      <div className="bg-white shadow-lg rounded-2xl p-6 w-full max-w-sm text-center">
        <button
          onClick={() => setCount((count) => count + 1)}
          className="w-full bg-blue-600 hover:bg-blue-700 text-white py-2 rounded-lg transition mb-4"
        >
          Compteur : {count}
        </button>

        <p className="text-gray-600">
          Modifie <code className="text-blue-500">src/App.jsx</code> et sauvegarde pour tester le HMR.
        </p>
      </div>

      <p className="mt-6 text-gray-500 text-sm">
        Clique sur les logos pour en savoir plus.
      </p>
    </div>
  );
}

export default App;
